#!/usr/bin/env python3
import argparse, json
import numpy as np
from pathlib import Path
from revision_common import *
ap=argparse.ArgumentParser(); ap.add_argument('--dataset',required=True); ap.add_argument('--data-root',required=True); ap.add_argument('--base-dump',required=True); ap.add_argument('--adjusted-dump',required=True); ap.add_argument('--split',choices=['valid','test'],default='test'); ap.add_argument('--bootstrap',type=int,default=5000); ap.add_argument('--permutations',type=int,default=5000); ap.add_argument('--seed',type=int,default=123); ap.add_argument('--out-json',default='results/query_bootstrap.json'); a=ap.parse_args(); rng=np.random.default_rng(a.seed); ne,nr,sp,h,filt=context(a.data_root,a.dataset,a.split); bs,tr,e=load_score_dump(a.base_dump); hs,htr,he=load_score_dump(a.adjusted_dump); q=canonicalize_queries(tr,e,nr); hq=canonicalize_queries(htr,he,nr); align_dumps(q,hq); rb=filtered_ranks(bs,q,filt); rh=filtered_ranks(hs,q,filt); d=1/rh.astype(float)-1/rb.astype(float); n=len(d); obs=float(d.mean()); boot=np.asarray([d[rng.integers(0,n,n)].mean() for _ in range(a.bootstrap)]); signs=rng.choice(np.array([-1.,1.]),size=(a.permutations,n)); perm=np.mean(signs*d[None,:],axis=1); p=float((np.sum(np.abs(perm)>=abs(obs))+1)/(len(perm)+1)); out={'n_queries':n,'observed_delta_MRR':obs,'bootstrap_CI95':[float(np.quantile(boot,.025)),float(np.quantile(boot,.975))],'sign_flip_permutation_p':p,'positive_query_fraction':float(np.mean(d>0)),'negative_query_fraction':float(np.mean(d<0)),'zero_query_fraction':float(np.mean(d==0))}; save_json(out,a.out_json); print(json.dumps(out,indent=2))
